def token_bucket(capacity, refill, events):
    def is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    if not is_int(capacity) or capacity < 0:
        raise ValueError("capacity must be a non-negative integer")
    if not is_int(refill) or refill < 0:
        raise ValueError("refill must be a non-negative integer")
    if not isinstance(events, (list, tuple)):
        raise ValueError("events must be a list or tuple")

    parsed = []
    for ev in events:
        if not isinstance(ev, tuple) or len(ev) != 2:
            raise ValueError("each event must be a length-2 tuple")
        ts, cost = ev
        if not is_int(ts) or ts < 0:
            raise ValueError("timestamp must be a non-negative integer")
        if not is_int(cost) or cost < 0:
            raise ValueError("cost must be a non-negative integer")
        parsed.append((ts, cost))

    for i in range(1, len(parsed)):
        if parsed[i][0] < parsed[i - 1][0]:
            raise ValueError("timestamps must be non-decreasing")

    tokens = capacity
    remainder = 0
    last_ts = 0
    result = []

    for ts, cost in parsed:
        elapsed = ts - last_ts
        last_ts = ts
        total = remainder + elapsed * refill
        gained = total // 1000
        remainder = total % 1000
        tokens = min(capacity, tokens + gained)

        if tokens >= cost:
            tokens -= cost
            result.append(True)
        else:
            result.append(False)

    return result
